let conversionQuoteMap={};
const novelMappingUI=conversionMappingUI,novelIssues=conversionIssues;
conversionMappingUI=function(r){return novelMappingUI(r)+((r.quoteAttributions||[]).length?`<section class="conversion-mapping"><h3>全部引号对白 · ${r.unresolvedQuotes.length} 句待确认</h3><p class="field-note">动作描写和连续对白不会直接当作角色名。没有明确说话提示的句子，请结合上下文指定。</p>${r.quoteAttributions.map((q,i)=>`<div class="quote-review"><small>第 ${q.line} 行 · 上文：${esc(q.previous)}</small><p>「${esc(q.text)}」</p><small>下文：${esc(q.next)}</small><select data-quote-map="${i}" aria-label="第 ${q.line} 行说话人"><option value="">选择这一句的说话人</option>${project.characters.map(c=>`<option value="${esc(c.id)}" ${q.speaker===c.id?'selected':''}>${esc(c.name)}</option>`).join('')}<option value="__narration__" ${q.asNarration?'selected':''}>保留引号原文为旁白</option></select></div>`).join('')}</section>`:'')};
conversionIssues=function(r,mode,plans){return novelIssues(r,mode,plans).concat(r.unresolvedQuotes?.length?['请确认引号对白的说话人，再写入工程。']:[])};
document.addEventListener('change',e=>{const index=e.target.dataset.quoteMap;if(index===undefined||!e.target.value)return;const quote=conversionResult?.quoteAttributions?.[Number(index)];if(quote){conversionQuoteMap[quote.key]=e.target.value;previewConversion()}});
